"use client";
// A dot-grid world map (Natural Earth land, generated by scripts/build-worldmap.mjs) with the two chains as live
// nodes and the Across bridge as an arc between them. Chains are not places: node positions are for illustration only.
import { useMemo } from "react";
import world from "@/lib/worldDots.json";
import type { ChainId } from "@/lib/recommend";

const W = 1000;
const COLS = world.rows[0].length;
const CELL = W / COLS;
const H = ((world.rows.length * world.step) / 360) * W;
const proj = (lon: number, lat: number) => ({ x: ((lon + 180) / 360) * W, y: ((world.latTop - lat) / (world.latTop - world.latBottom)) * H });

const POS: Record<ChainId, { lon: number; lat: number }> = { unichain: { lon: -98, lat: 39 }, base: { lon: 18, lat: 47 } };
const NAME: Record<ChainId, string> = { unichain: "Unichain Sepolia", base: "Base Sepolia" };
const CHAINS: ChainId[] = ["unichain", "base"];

export interface WorldMapProps {
  activity?: Record<ChainId, number>;
  pool?: Partial<Record<ChainId, string>>;
  /** The chain liquidity should leave, and the one it should go to, when one is much busier. */
  flow?: { from: ChainId; to: ChainId } | null;
  bridge?: { fillSec: number; feePct: number };
}

export function WorldMap({ activity, pool, flow, bridge }: WorldMapProps) {
  const dots = useMemo(() => {
    let d = "";
    world.rows.forEach((row, r) => {
      for (let c = 0; c < COLS; c++) if (row[c] === "1") d += `M${((c + 0.5) * CELL).toFixed(1)} ${((r + 0.5) * CELL).toFixed(1)}h0`;
    });
    return d;
  }, []);

  const at: Record<ChainId, { x: number; y: number }> = { unichain: proj(POS.unichain.lon, POS.unichain.lat), base: proj(POS.base.lon, POS.base.lat) };
  const from = at[flow?.from ?? "unichain"];
  const to = at[flow?.to ?? "base"];
  const path = `M${from.x} ${from.y} Q${(from.x + to.x) / 2} ${Math.min(from.y, to.y) - 120} ${to.x} ${to.y}`;
  const ring = (c: ChainId) => 9 + Math.min(activity?.[c] ?? 0, 12) * 1.6;
  const hot = flow?.to;

  return (
    <figure className="worldmap" aria-label="World map with Unichain and Base as nodes joined by the Across bridge">
      <svg viewBox={`0 0 ${W} ${H}`} aria-hidden="true" preserveAspectRatio="xMidYMid meet">
        <path className="wm-land" d={dots} />
        <path className="wm-arc-base" d={path} />
        <path className={`wm-arc${flow ? " flowing" : ""}`} d={path} />
        {CHAINS.map((c) => (
          <g key={c} className={`wm-node${hot === c ? " hot" : ""}`}>
            <circle className="wm-ring" cx={at[c].x} cy={at[c].y} r={ring(c)} />
            <circle className="wm-pulse" cx={at[c].x} cy={at[c].y} r={ring(c)} />
            <circle className="wm-core" cx={at[c].x} cy={at[c].y} r="6" />
          </g>
        ))}
      </svg>
      {flow && <span className="wm-packet" style={{ offsetPath: `path("${path}")` }} aria-hidden="true" />}
      {CHAINS.map((c) => (
        <div key={c} className={`wm-label${hot === c ? " hot" : ""}`} style={{ left: `${(at[c].x / W) * 100}%`, top: `${(at[c].y / H) * 100}%` }}>
          <b>{NAME[c]}</b>
          <span>{activity ? `${activity[c].toFixed(1)} recent swaps` : "reading…"}</span>
          {pool?.[c] && <span>{pool[c]} pool units</span>}
        </div>
      ))}
      <figcaption className="wm-cap">
        <span className="sub">Across bridge</span>
        <b>{bridge ? `~${bridge.fillSec} s` : "–"}</b>
        <span className="cap dim">{flow ? `Reactive suggests ${NAME[flow.from]} → ${NAME[flow.to]}` : "balanced"}</span>
      </figcaption>
      <p className="cap dim wm-note">Chains are not places; the nodes sit on the map for illustration. Ring size follows recent swap activity.</p>
    </figure>
  );
}
